<div class="page-head"><h1>Reports</h1><div class="actions"><?php if (App\Core\Auth::hasRole('manager')): ?><a class="btn" href="/reports/survey.csv">Export survey CSV</a><?php endif; ?></div></div>
<div class="cols">
<section class="card"><h2>Results by channel</h2><table class="tbl compact"><tbody><?php foreach ($results as $r): ?><tr><td><?= e($r['channel']) ?></td><td><?= e(result_label($r['result'])) ?></td><td class="r"><?= fmt_num($r['n']) ?></td></tr><?php endforeach; ?><?php if (!$results): ?><tr><td class="muted">No data yet.</td></tr><?php endif; ?></tbody></table></section>
<section class="card"><h2>Daily activity (30 days)</h2><div class="bars"><?php $max = max(1, ...array_map(fn($d) => (int) $d['n'], $daily ?: [['n' => 1]])); foreach ($daily as $d): ?><div class="bar" title="<?= e($d['d']) ?>: <?= (int) $d['n'] ?> attempts, <?= (int) $d['c'] ?> conversations"><i style="height:<?= (int) (100 * $d['n'] / $max) ?>%"></i><b style="height:<?= (int) (100 * $d['c'] / $max) ?>%"></b></div><?php endforeach; ?></div><?php if (!$daily): ?><p class="muted">No activity yet.</p><?php endif; ?></section>
<section class="card wide"><h2>Survey results</h2>
<?php foreach ($questions as $q): ?><h3><?= e($q['question']) ?></h3><table class="tbl compact"><tbody><?php foreach ($answers[$q['id']] as $a): ?><tr><td><?= e((string) $a['answer']) ?></td><td class="r"><?= fmt_num($a['n']) ?></td></tr><?php endforeach; ?><?php if (!$answers[$q['id']]): ?><tr><td class="muted">No answers yet.</td></tr><?php endif; ?></tbody></table><?php endforeach; ?>
<?php if (!$questions): ?><p class="muted">No active survey questions. <a href="/settings/surveys">Add some</a>.</p><?php endif; ?></section>
<section class="card"><h2>Support by precinct</h2><p class="small muted">Average of 1-5 scale answers (lower is stronger support).</p><table class="tbl compact"><thead><tr><th>Precinct</th><th class="r">Avg</th><th class="r">n</th></tr></thead><tbody><?php foreach ($supportByPrecinct as $r): ?><tr><td><?= e((string) $r['precinct']) ?></td><td class="r"><?= e((string) $r['avg_support']) ?></td><td class="r"><?= (int) $r['n'] ?></td></tr><?php endforeach; ?></tbody></table></section>
<section class="card"><h2>Contact attempts by precinct</h2><table class="tbl compact"><thead><tr><th>Precinct</th><th class="r">Attempts</th><th class="r">Conversations</th><th class="r">Voters reached</th></tr></thead><tbody><?php foreach ($byPrecinct as $r): ?><tr><td><?= e((string) $r['precinct']) ?></td><td class="r"><?= (int) $r['attempts'] ?></td><td class="r"><?= (int) $r['contacts'] ?></td><td class="r"><?= (int) $r['voters_reached'] ?></td></tr><?php endforeach; ?></tbody></table></section>
<section class="card wide"><h2>Volunteer leaderboard</h2><table class="tbl compact"><thead><tr><th>Volunteer</th><th class="r">Attempts</th><th class="r">Conversations</th><th class="r">Days active</th></tr></thead><tbody><?php foreach ($leaders as $l): ?><tr><td><?= e($l['name']) ?></td><td class="r"><?= fmt_num($l['attempts']) ?></td><td class="r"><?= fmt_num($l['contacts']) ?></td><td class="r"><?= (int) $l['days_active'] ?></td></tr><?php endforeach; ?></tbody></table></section>
</div>
